-- Disposable local Supabase only. Every fixture is rolled back.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(31);
select ok((select relrowsecurity from pg_class where oid='private.runner_state'::regclass),'runner state RLS');
select ok(not has_table_privilege('authenticated','private.runner_state','SELECT'),'customer cannot read runner state');
select ok(not has_table_privilege('service_role','private.runner_state','UPDATE'),'backend only narrow functions');
select ok(not has_function_privilege('anon','public.iojh_runner_begin()','EXECUTE'),'anon cannot begin');
select ok(not has_function_privilege('authenticated','public.iojh_runner_claim(uuid,text,boolean,text,uuid)','EXECUTE'),'customer cannot claim');
select ok(not has_function_privilege('authenticated','public.iojh_runner_authorize_send(uuid,uuid,uuid,bigint,text)','EXECUTE'),'customer cannot authorize sending');
select ok(has_function_privilege('service_role','public.iojh_runner_claim(uuid,text,boolean,text,uuid)','EXECUTE'),'backend can claim');
set local role authenticated;
select throws_ok('select public.iojh_runner_admin_health()','42501',null,'customer health denied');
reset role;
insert into auth.users(id,instance_id,aud,"role",email,email_confirmed_at,created_at,updated_at,raw_user_meta_data) values
('c7000000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','c07c-customer@example.invalid',now(),now(),now(),' {"role":"admin"}'::jsonb),
('c7000000-0000-4000-8000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','c07c-owner@example.invalid',now(),now(),now(),'{}'::jsonb);
select set_config('request.jwt.claim.sub','c7000000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"c7000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
set local role authenticated;
select throws_ok('select public.iojh_runner_admin_health()','42501',null,'forged role health denied');
reset role;
select set_config('iojh.admin_change_reason','C07c disposable administrator fixture',true);
insert into private.admin_memberships(user_id,active) values('c7000000-0000-4000-8000-000000000002',true);
insert into auth.mfa_factors(id,user_id,friendly_name,factor_type,status,created_at,updated_at)
values('c8000000-0000-4000-8000-000000000002','c7000000-0000-4000-8000-000000000002','C07c fixture','totp','verified',now(),now());
select set_config('request.jwt.claim.sub','c7000000-0000-4000-8000-000000000002',true);
select set_config('request.jwt.claims','{"sub":"c7000000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal1"}',true);
set local role authenticated;
select throws_ok('select public.iojh_runner_admin_health()','42501',null,'AAL1 admin health denied');
select set_config('request.jwt.claims','{"sub":"c7000000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);
select ok(public.iojh_runner_admin_health() ? 'due','AAL2 verified current admin sees aggregate');
select ok(not (public.iojh_runner_admin_health() ? 'runToken'),'lease/runner tokens excluded');
reset role;
select set_config('iojh.admin_change_reason','C07c disposable administrator revocation',true);
update private.admin_memberships set active=false,revoked_at=now() where user_id='c7000000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok('select public.iojh_runner_admin_health()','42501',null,'revoked AAL2 admin denied');
reset role;
select set_config('iojh.test.notice',public.iojh_notifications_enqueue_fixture('C07C-TEST-0001','c07c-notice-0001','en')::text,true);
select set_config('iojh.test.probe',public.iojh_jobs_enqueue_probe('b7000000-0000-4000-8000-000000000001','c07c-probe-0001',null,2)::text,true);
set local role service_role;
select set_config('iojh.test.run',public.iojh_runner_begin()::text,true);
select ok(current_setting('iojh.test.run')<> '', 'run acquired');
select is(public.iojh_runner_begin(),null::uuid,'overlap denied');
create temp table c07c_claim as select x from public.iojh_runner_claim(current_setting('iojh.test.run')::uuid,'c07c-test',false,null,null) x;
select is((select x->>'kind' from c07c_claim),'ops.probe','probe only claim');
select is((select count(*) from public.iojh_runner_claim(current_setting('iojh.test.run')::uuid,'c07c-test',false,null,null)),0::bigint,'disabled email not claimed');
reset role;
select is((select attempts from private.jobs j join private.notification_records n on n.job_id=j.id where n.id=current_setting('iojh.test.notice')::uuid),0,'disabled email attempt budget unchanged');
select ok((select public.iojh_jobs_complete((x->>'jobId')::uuid,(x->>'leaseToken')::uuid,(x->>'leaseGeneration')::bigint) from c07c_claim),'probe completes fenced');
select is((select count(*) from public.iojh_runner_claim(current_setting('iojh.test.run')::uuid,'c07c-test',true,'wrong@example.org',current_setting('iojh.test.notice')::uuid)),0::bigint,'unapproved recipient remains unclaimed');
create temp table c07c_mail as select x from public.iojh_runner_claim(current_setting('iojh.test.run')::uuid,'c07c-test',true,'fixture@example.invalid',current_setting('iojh.test.notice')::uuid) x;
select is((select x->>'kind' from c07c_mail),'notification.email','approved disposable fixture claimed');
select is((select public.iojh_notifications_prepare((x->>'jobId')::uuid,(x->>'leaseToken')::uuid,(x->>'leaseGeneration')::bigint)->>'action' from c07c_mail),'send','prepares fixture without external send');
select is((select public.iojh_runner_authorize_send(current_setting('iojh.test.run')::uuid,(x->>'jobId')::uuid,(x->>'leaseToken')::uuid,(x->>'leaseGeneration')::bigint,repeat('a',64)) from c07c_mail),'send','reserves exact provider content and cooldown');
select is((select public.iojh_runner_authorize_send(current_setting('iojh.test.run')::uuid,(x->>'jobId')::uuid,(x->>'leaseToken')::uuid,(x->>'leaseGeneration')::bigint,repeat('a',64)) from c07c_mail),'stale','same generation cannot reserve twice');
update private.jobs set lease_expires_at=clock_timestamp()-interval '1 second',max_attempts=attempts where id=(select (x->>'jobId')::uuid from c07c_mail);
select is((select count(*) from public.iojh_runner_claim(current_setting('iojh.test.run')::uuid,'c07c-test',false,null,null)),0::bigint,'sweep does not claim disabled email');
select is((select status from private.notification_records where id=current_setting('iojh.test.notice')::uuid),'uncertain','exhausted dispatched notification becomes uncertain');
-- Terminal provider outcomes with real SQL transitions, not real network requests.
select set_config('iojh.test.notice2',public.iojh_notifications_enqueue_fixture('C07C-TEST-0002','c07c-notice-0002','en')::text,true);
update private.runner_state set cooldown_until='-infinity' where id=1;
create temp table c07c_mail2 as select x from public.iojh_runner_claim(current_setting('iojh.test.run')::uuid,'c07c-test',true,'fixture@example.invalid',current_setting('iojh.test.notice2')::uuid) x;
select public.iojh_notifications_prepare((x->>'jobId')::uuid,(x->>'leaseToken')::uuid,(x->>'leaseGeneration')::bigint) from c07c_mail2;
select public.iojh_runner_authorize_send(current_setting('iojh.test.run')::uuid,(x->>'jobId')::uuid,(x->>'leaseToken')::uuid,(x->>'leaseGeneration')::bigint,repeat('b',64)) from c07c_mail2;
update private.jobs set max_attempts=attempts where id=(select (x->>'jobId')::uuid from c07c_mail2);
select is((select public.iojh_notifications_finish((x->>'jobId')::uuid,(x->>'leaseToken')::uuid,(x->>'leaseGeneration')::bigint,'retry',null,'timeout') from c07c_mail2),'uncertain','ambiguous timeout at retry ceiling quarantines');
select set_config('iojh.test.notice3',public.iojh_notifications_enqueue_fixture('C07C-TEST-0003','c07c-notice-0003','en')::text,true);
update private.runner_state set cooldown_until='-infinity' where id=1;
create temp table c07c_mail3 as select x from public.iojh_runner_claim(current_setting('iojh.test.run')::uuid,'c07c-test',true,'fixture@example.invalid',current_setting('iojh.test.notice3')::uuid) x;
select public.iojh_notifications_prepare((x->>'jobId')::uuid,(x->>'leaseToken')::uuid,(x->>'leaseGeneration')::bigint) from c07c_mail3;
select public.iojh_runner_authorize_send(current_setting('iojh.test.run')::uuid,(x->>'jobId')::uuid,(x->>'leaseToken')::uuid,(x->>'leaseGeneration')::bigint,repeat('c',64)) from c07c_mail3;
select is((select public.iojh_notifications_finish((x->>'jobId')::uuid,(x->>'leaseToken')::uuid,(x->>'leaseGeneration')::bigint,'dead',null,'provider_rejected') from c07c_mail3),'failed','known first permanent rejection is failed');
select is((select state from private.jobs j join private.notification_records n on j.id=n.job_id where n.id=current_setting('iojh.test.notice3')::uuid),'dead','permanent rejection does not auto-retry');
select is((select count(*) from private.notification_delivery_attempts where notification_id=current_setting('iojh.test.notice3')::uuid),1::bigint,'delivery evidence retained');
select ok(public.iojh_runner_end(current_setting('iojh.test.run')::uuid,true,'{"claimed":2}'::jsonb),'valid run ends');
select * from finish();
rollback;
